"""Errors raised by minisql."""


class QueryError(Exception):
    """Raised for any problem with a query."""

"""Abstract syntax tree nodes for minisql.

Expression nodes all carry ``text``: the expression exactly as it appeared in
the query (from the first token through the last).  It is excluded from
comparison so that two structurally identical expressions compare equal even
when written with different whitespace or letter case.
"""

from dataclasses import dataclass, field
from typing import Any, Iterator, List, Optional

AGGREGATE_NAMES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})


@dataclass
class Expr:
    text: str = field(default="", compare=False, repr=False)


@dataclass
class Literal(Expr):
    value: Any = None


@dataclass
class Column(Expr):
    name: str = ""


@dataclass
class Unary(Expr):
    op: str = ""
    operand: Optional[Expr] = None


@dataclass
class Binary(Expr):
    op: str = ""
    left: Optional[Expr] = None
    right: Optional[Expr] = None


@dataclass
class IsNull(Expr):
    operand: Optional[Expr] = None
    negated: bool = False


@dataclass
class InList(Expr):
    operand: Optional[Expr] = None
    items: List[Expr] = field(default_factory=list)
    negated: bool = False


@dataclass
class Between(Expr):
    operand: Optional[Expr] = None
    low: Optional[Expr] = None
    high: Optional[Expr] = None
    negated: bool = False


@dataclass
class Like(Expr):
    operand: Optional[Expr] = None
    pattern: Optional[Expr] = None
    negated: bool = False


@dataclass
class FuncCall(Expr):
    name: str = ""
    args: List[Expr] = field(default_factory=list)
    star: bool = False


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Expr
    descending: bool = False


@dataclass
class Select:
    distinct: bool = False
    items: List[SelectItem] = field(default_factory=list)
    table: str = ""
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


def is_aggregate(node: Optional[Expr]) -> bool:
    """Return whether *node* is an aggregate function call."""
    return isinstance(node, FuncCall) and node.name.upper() in AGGREGATE_NAMES


def children(node: Optional[Expr]) -> Iterator[Expr]:
    """Yield the direct child expressions of *node*."""
    if node is None:
        return
    if isinstance(node, Unary):
        yield node.operand
    elif isinstance(node, Binary):
        yield node.left
        yield node.right
    elif isinstance(node, IsNull):
        yield node.operand
    elif isinstance(node, InList):
        yield node.operand
        yield from node.items
    elif isinstance(node, Between):
        yield node.operand
        yield node.low
        yield node.high
    elif isinstance(node, Like):
        yield node.operand
        yield node.pattern
    elif isinstance(node, FuncCall):
        yield from node.args


def walk(node: Optional[Expr]) -> Iterator[Expr]:
    """Yield *node* and every expression nested inside it."""
    if node is None:
        return
    yield node
    for child in children(node):
        yield from walk(child)


def contains_aggregate(node: Optional[Expr]) -> bool:
    """Return whether *node* contains an aggregate function call."""
    return any(is_aggregate(part) for part in walk(node))


def column_refs(node: Optional[Expr]) -> Iterator[Column]:
    """Yield every column reference in *node*."""
    for part in walk(node):
        if isinstance(part, Column):
            yield part

