_SCALAR_ARITY = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


def _validate_functions(query):
    """Check scalar function names and argument counts statically.

    This ensures that an unknown function or a bad argument count is an error
    even when the table has no rows (and the expression would never actually
    be evaluated).
    """
    roots = [
        item.expr for item in query.items if not isinstance(item.expr, Star)
    ]
    roots.append(query.where)
    roots.extend(query.group_by)
    roots.append(query.having)
    roots.extend(item.expr for item in query.order_by)

    for root in roots:
        for node in walk(root):
            if not isinstance(node, FuncCall) or is_aggregate(node):
                continue
            name = node.name.upper()
            if name not in _SCALAR_ARITY:
                raise QueryError("unknown function: {}".format(node.name))
            if node.star:
                raise QueryError("function {} does not accept '*'".format(name))
            minimum, maximum = _SCALAR_ARITY[name]
            count = len(node.args)
            if count < minimum or (maximum is not None and count > maximum):
                if maximum == minimum == 1:
                    message = "{} takes exactly one argument".format(name)
                elif maximum is None:
                    message = "{} requires at least one argument".format(name)
                else:
                    message = "{} takes one or two arguments".format(name)
                raise QueryError(message)


