def _round_to_int(value):
    if _is_int(value):
        return value
    try:
        number = Decimal(str(value))
        with localcontext() as context:
            context.prec = max(100, abs(number.adjusted()) + 10)
            rounded = number.quantize(Decimal(1), rounding=ROUND_HALF_UP)
        return int(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("ROUND: value out of range")


def _round_to_places(value, places):
    try:
        number = Decimal(str(value))
        with localcontext() as context:
            # Enough precision for the value's integer part plus the requested
            # fractional places.  Decimal's default precision (28) is too
            # small for values such as ROUND(1.2345, 100).
            context.prec = max(100, abs(number.adjusted()) + abs(places) + 10)
            exponent = Decimal(1).scaleb(-places)
            rounded = number.quantize(exponent, rounding=ROUND_HALF_UP)
        return float(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("ROUND: value out of range")

